import { useState, useEffect, useMemo } from 'react';
import {
  Box,
  Container,
  Typography,
  Paper,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
  CircularProgress,
  Alert
} from '@mui/material';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter
} from 'recharts';
import { getSavedData } from '../services/firebaseService';
import { KjeldahlData } from '../services/firebaseService';

interface VisualizationOption {
  value: 'factorsByCategory' | 'aminoAcidDistribution' | 'nitrogenVsFactor' | 'aminoAcidVsFactor';
  label: string;
}

interface IndividualSpeciesOption {
  value: 'factor' | 'nitrogen' | 'aminoAcids';
  label: string;
}

interface AminoAcidData {
  aminoAcid: string;
  value: number;
  unit: string;
}

const visualizationOptions: VisualizationOption[] = [
  { value: 'factorsByCategory', label: 'Conversion Factors by Category' },
  { value: 'aminoAcidDistribution', label: 'Amino Acid Distribution' },
  { value: 'nitrogenVsFactor', label: 'Nitrogen Content vs Conversion Factor' },
  { value: 'aminoAcidVsFactor', label: 'Total Amino Acids vs Conversion Factor' }
];

const individualSpeciesOptions: IndividualSpeciesOption[] = [
  { value: 'factor', label: 'Conversion Factor' },
  { value: 'nitrogen', label: 'Nitrogen Content' },
  { value: 'aminoAcids', label: 'Amino Acids' }
];

interface TooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    payload: {
      name: string;
      [key: string]: any;
    };
  }>;
}

const CustomTooltip = ({ active, payload }: TooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <Paper sx={{ p: 2, backgroundColor: 'rgba(255, 255, 255, 0.9)' }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1 }}>
          {payload[0].payload.name}
        </Typography>
        {payload.map((item, index) => (
          <Typography key={index} variant="body2">
            {item.name}: {item.value}
          </Typography>
        ))}
      </Paper>
    );
  }
  return null;
};

const CustomAxisTick = ({ x, y, payload }: any) => {
  return (
    <g transform={`translate(${x},${y})`}>
      <text
        x={0}
        y={0}
        dy={16}
        textAnchor="end"
        fill="#666"
        transform="rotate(-45)"
        style={{ fontSize: '12px' }}
      >
        {payload.value}
      </text>
    </g>
  );
};

export default function Dashboard() {
  const [data, setData] = useState<KjeldahlData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedVisualization, setSelectedVisualization] = useState<VisualizationOption['value']>('factorsByCategory');
  const [selectedCategories, setSelectedCategories] = useState<string[]>(['all']);
  const [selectedSpeciesVariable, setSelectedSpeciesVariable] = useState<IndividualSpeciesOption['value']>('factor');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);
      const savedData = await getSavedData();
      setData(savedData);
    } catch (err) {
      setError('Failed to load data. Please try again later.');
      console.error('Error loading data:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleVisualizationChange = (event: SelectChangeEvent) => {
    setSelectedVisualization(event.target.value as VisualizationOption['value']);
  };

  const handleCategoryChange = (event: SelectChangeEvent<string[]>) => {
    const value = event.target.value;
    if (typeof value === 'string') {
      setSelectedCategories([value]);
    } else {
      // If "all" is selected, clear other selections
      if (value.includes('all')) {
        setSelectedCategories(['all']);
      } else {
        setSelectedCategories(value);
      }
    }
  };

  const handleSpeciesVariableChange = (event: SelectChangeEvent) => {
    setSelectedSpeciesVariable(event.target.value as IndividualSpeciesOption['value']);
  };

  const categories = useMemo(() => {
    const uniqueCategories = new Set(data.map(item => item.foodCategory));
    return Array.from(uniqueCategories);
  }, [data]);

  const filteredData = useMemo(() => {
    if (selectedCategories.includes('all')) {
      return data;
    }
    return data.filter(item => selectedCategories.includes(item.foodCategory || ''));
  }, [data, selectedCategories]);

  const prepareFactorsByCategoryData = useMemo(() => {
    const categoryData = new Map<string, { totalFactor: number; count: number }>();
    
    filteredData.forEach(entry => {
      if (entry.factor && entry.foodCategory) {
        const current = categoryData.get(entry.foodCategory) || { totalFactor: 0, count: 0 };
        categoryData.set(entry.foodCategory, {
          totalFactor: current.totalFactor + entry.factor,
          count: current.count + 1
        });
      }
    });

    return Array.from(categoryData.entries()).map(([category, data]) => ({
      category,
      averageFactor: Number((data.count > 0 ? data.totalFactor / data.count : 0).toFixed(2))
    }));
  }, [filteredData]);

  const prepareAminoAcidData = useMemo(() => {
    const aminoAcidMap = new Map<string, { total: number; count: number }>();
    
    filteredData.forEach(entry => {
      if (entry.aminoAcids) {
        Object.entries(entry.aminoAcids).forEach(([aminoAcid, data]) => {
          if (data && typeof data === 'object' && 'value' in data) {
            const aminoAcidData = data as { value: number; unit: string };
            const current = aminoAcidMap.get(aminoAcid) || { total: 0, count: 0 };
            aminoAcidMap.set(aminoAcid, {
              total: current.total + (aminoAcidData.value || 0),
              count: current.count + 1
            });
          }
        });
      }
    });

    return Array.from(aminoAcidMap.entries()).map(([aminoAcid, data]) => ({
      aminoAcid,
      value: Number((data.count > 0 ? data.total / data.count : 0).toFixed(2))
    }));
  }, [filteredData]);

  const prepareNitrogenVsFactorData = useMemo(() => {
    return filteredData
      .filter(entry => entry.kjeldahlNitrogen !== null && entry.factor !== null)
      .map(entry => ({
        nitrogen: Number((entry.kjeldahlNitrogen || 0).toFixed(2)),
        factor: Number((entry.factor || 0).toFixed(2)),
        name: entry.scientificName || 'Unknown'
      }));
  }, [filteredData]);

  const prepareAminoAcidVsFactorData = useMemo(() => {
    return filteredData
      .filter(entry => entry.factor !== null)
      .map(entry => {
        const totalAminoAcids = entry.aminoAcids
          ? Object.values(entry.aminoAcids).reduce((sum, data) => {
              if (data && typeof data === 'object' && 'value' in data) {
                const aminoAcidData = data as { value: number; unit: string };
                return (sum || 0) + (aminoAcidData.value || 0);
              }
              return sum || 0;
            }, 0)
          : 0;
        return {
          totalAminoAcids: Number((totalAminoAcids || 0).toFixed(2)),
          factor: Number((entry.factor || 0).toFixed(2)),
          name: entry.scientificName || 'Unknown'
        };
      });
  }, [filteredData]);

  const prepareIndividualSpeciesData = useMemo(() => {
    return filteredData.map(entry => {
      const aminoAcidValues: AminoAcidData[] = entry.aminoAcids
        ? Object.entries(entry.aminoAcids)
            .map(([acid, data]) => {
              if (data && typeof data === 'object' && 'value' in data) {
                const aminoAcidData = data as { value: number; unit: string };
                return {
                  aminoAcid: acid,
                  value: Number((aminoAcidData.value || 0).toFixed(2)),
                  unit: aminoAcidData.unit || 'mg/g'
                };
              }
              return null;
            })
            .filter((item): item is NonNullable<typeof item> => item !== null)
        : [];
      
      return {
        scientificName: entry.scientificName || 'Unknown',
        foodCategory: entry.foodCategory || 'Unknown',
        factor: entry.factor ? Number(entry.factor.toFixed(2)) : null,
        kjeldahlNitrogen: entry.kjeldahlNitrogen ? Number(entry.kjeldahlNitrogen.toFixed(2)) : null,
        aminoAcids: aminoAcidValues
      };
    });
  }, [filteredData]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Alert severity="error">{error}</Alert>
      </Container>
    );
  }

  if (data.length === 0) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Alert severity="info">No data available. Please add some entries first.</Alert>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Typography variant="h4" component="h1" gutterBottom>
        Kjeldahl Data Dashboard
      </Typography>
      
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <FormControl fullWidth>
            <InputLabel>Visualization Type</InputLabel>
            <Select
              value={selectedVisualization}
              onChange={handleVisualizationChange}
              label="Visualization Type"
            >
              {visualizationOptions.map(option => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>
        
        <Grid item xs={12} md={6}>
          <FormControl fullWidth>
            <InputLabel>Food Category</InputLabel>
            <Select
              multiple
              value={selectedCategories}
              onChange={handleCategoryChange}
              label="Food Category"
              renderValue={(selected) => {
                if (selected.includes('all')) {
                  return 'All Categories';
                }
                return selected.join(', ');
              }}
            >
              <MenuItem value="all">All Categories</MenuItem>
              {categories.map(category => (
                <MenuItem key={category} value={category}>
                  {category}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3 }}>
            {selectedVisualization === 'factorsByCategory' && prepareFactorsByCategoryData.length > 0 && (
              <ResponsiveContainer width="100%" height={400}>
                <BarChart data={prepareFactorsByCategoryData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis
                    dataKey="category"
                    tick={<CustomAxisTick />}
                    interval={0}
                    height={100}
                  />
                  <YAxis
                    label={{ value: 'Conversion Factor', angle: -90, position: 'insideLeft' }}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend />
                  <Bar
                    dataKey="averageFactor"
                    name="Average Conversion Factor"
                    fill="#8884d8"
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            )}

            {selectedVisualization === 'aminoAcidDistribution' && prepareAminoAcidData.length > 0 && (
              <ResponsiveContainer width="100%" height={400}>
                <BarChart data={prepareAminoAcidData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis
                    dataKey="aminoAcid"
                    tick={<CustomAxisTick />}
                    interval={0}
                    height={100}
                  />
                  <YAxis
                    label={{ value: 'Content (mg/g)', angle: -90, position: 'insideLeft' }}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend />
                  <Bar
                    dataKey="value"
                    name="Average Content"
                    fill="#82ca9d"
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            )}

            {selectedVisualization === 'nitrogenVsFactor' && prepareNitrogenVsFactorData.length > 0 && (
              <ResponsiveContainer width="100%" height={400}>
                <ScatterChart>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis
                    type="number"
                    dataKey="nitrogen"
                    name="Nitrogen Content"
                    label={{ value: 'Nitrogen Content', position: 'insideBottom', offset: -5 }}
                  />
                  <YAxis
                    type="number"
                    dataKey="factor"
                    name="Conversion Factor"
                    label={{ value: 'Conversion Factor', angle: -90, position: 'insideLeft' }}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend />
                  <Scatter
                    data={prepareNitrogenVsFactorData}
                    fill="#8884d8"
                    shape="circle"
                    radius={5}
                  />
                </ScatterChart>
              </ResponsiveContainer>
            )}

            {selectedVisualization === 'aminoAcidVsFactor' && prepareAminoAcidVsFactorData.length > 0 && (
              <ResponsiveContainer width="100%" height={400}>
                <ScatterChart>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis
                    type="number"
                    dataKey="totalAminoAcids"
                    name="Total Amino Acids"
                    label={{ value: 'Total Amino Acids', position: 'insideBottom', offset: -5 }}
                  />
                  <YAxis
                    type="number"
                    dataKey="factor"
                    name="Conversion Factor"
                    label={{ value: 'Conversion Factor', angle: -90, position: 'insideLeft' }}
                  />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend />
                  <Scatter
                    data={prepareAminoAcidVsFactorData}
                    fill="#82ca9d"
                    shape="circle"
                    radius={5}
                  />
                </ScatterChart>
              </ResponsiveContainer>
            )}
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              Individual Species Analysis
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <FormControl fullWidth>
                  <InputLabel>Variable</InputLabel>
                  <Select
                    value={selectedSpeciesVariable}
                    onChange={handleSpeciesVariableChange}
                    label="Variable"
                  >
                    {individualSpeciesOptions.map(option => (
                      <MenuItem key={option.value} value={option.value}>
                        {option.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
            </Grid>
            <Box sx={{ mt: 2 }}>
              {selectedSpeciesVariable === 'factor' && prepareIndividualSpeciesData.length > 0 && (
                <ResponsiveContainer width="100%" height={400}>
                  <BarChart data={prepareIndividualSpeciesData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis
                      dataKey="scientificName"
                      tick={<CustomAxisTick />}
                      interval={0}
                      height={100}
                    />
                    <YAxis
                      label={{ value: 'Conversion Factor', angle: -90, position: 'insideLeft' }}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend />
                    <Bar
                      dataKey="factor"
                      name="Conversion Factor"
                      fill="#82ca9d"
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              )}
              {selectedSpeciesVariable === 'nitrogen' && prepareIndividualSpeciesData.length > 0 && (
                <ResponsiveContainer width="100%" height={400}>
                  <BarChart data={prepareIndividualSpeciesData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis
                      dataKey="scientificName"
                      tick={<CustomAxisTick />}
                      interval={0}
                      height={100}
                    />
                    <YAxis
                      label={{ value: 'Nitrogen Content', angle: -90, position: 'insideLeft' }}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend />
                    <Bar
                      dataKey="kjeldahlNitrogen"
                      name="Nitrogen Content"
                      fill="#8884d8"
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              )}
              {selectedSpeciesVariable === 'aminoAcids' && prepareIndividualSpeciesData.length > 0 && prepareIndividualSpeciesData[0]?.aminoAcids.length > 0 && (
                <ResponsiveContainer width="100%" height={400}>
                  <BarChart data={prepareIndividualSpeciesData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis
                      dataKey="scientificName"
                      tick={<CustomAxisTick />}
                      interval={0}
                      height={100}
                    />
                    <YAxis
                      label={{ value: 'Content (mg/g)', angle: -90, position: 'insideLeft' }}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend />
                    {prepareIndividualSpeciesData[0].aminoAcids.map((aa, index) => (
                      <Bar
                        key={aa.aminoAcid}
                        dataKey={`aminoAcids[${index}].value`}
                        name={aa.aminoAcid}
                        fill={`hsl(${(index * 137.5) % 360}, 70%, 50%)`}
                        radius={[4, 4, 0, 0]}
                      />
                    ))}
                  </BarChart>
                </ResponsiveContainer>
              )}
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Container>
  );
} 