// Add type for sortable fields
type SortableField = keyof Pick<KjeldahlData, 'scientificName' | 'foodCategory' | 'factor'>;

interface AminoAcidData {
  value: number;
  unit: string;
}

interface FormData {
  scientificName: string;
  foodCategory: string;
  aminoAcids: Record<string, AminoAcidData>;
  kjeldahlNitrogen: number | null;
  kjeldahlNitrogenUnit: 'total nitrogen' | 'crude protein';
  kjeldahlNitrogenBasis: 'dry weight' | 'wet weight';
  kjeldahlNitrogenFactor: number | null;
  moistureContent: number | null;
}

interface LocalKjeldahlData extends FormData {
  id: string;
  factor: number;
  savedWithKey: string;
  authors: string;
  year: string;
  title: string;
  journal: string;
  volume: string;
  issue: string;
  pages: string;
  doi: string;
  date: string;
  lastEditedBy?: string;
  lastEditedDate?: string;
  editHistory?: Array<{
    date: string;
    editedBy: string;
    changes: Record<string, any>;
  }>;
}

// Convert database KjeldahlData to LocalKjeldahlData
const convertFromDatabaseKjeldahlData = (dbData: KjeldahlData): LocalKjeldahlData => {
  if (!dbData.id) {
    throw new Error('Database entry is missing an ID');
  }

  const aminoAcids: Record<string, AminoAcidData> = {};
  Object.entries(dbData.aminoAcids).forEach(([key, value]) => {
    aminoAcids[key] = { value: value || 0, unit: 'mg/g' };
  });

  return {
    id: dbData.id,
    scientificName: dbData.scientificName,
    foodCategory: dbData.foodCategory,
    aminoAcids,
    kjeldahlNitrogen: dbData.kjeldahlNitrogen,
    kjeldahlNitrogenUnit: dbData.kjeldahlNitrogenUnit === 'totalNitrogenPercent' ? 'total nitrogen' : 'crude protein',
    kjeldahlNitrogenBasis: dbData.kjeldahlNitrogenBasis === 'dryWeight' ? 'dry weight' : 'wet weight',
    kjeldahlNitrogenFactor: dbData.kjeldahlNitrogenFactor,
    moistureContent: dbData.moistureContent,
    factor: dbData.factor,
    authors: dbData.authors,
    year: dbData.year,
    title: dbData.title,
    journal: dbData.journal,
    volume: dbData.volume,
    issue: dbData.issue,
    pages: dbData.pages,
    doi: dbData.doi,
    date: dbData.date,
    savedWithKey: dbData.savedWithKey,
    lastEditedBy: dbData.lastEditedBy,
    lastEditedDate: dbData.lastEditedDate,
    editHistory: dbData.editHistory?.map(edit => ({
      date: edit.date,
      editedBy: edit.editedBy,
      changes: edit.changes
    }))
  };
};

// Convert LocalKjeldahlData to database KjeldahlData
const convertToDatabaseKjeldahlData = (localData: LocalKjeldahlData): KjeldahlData => {
  const aminoAcids: Record<string, number | null> = {};
  Object.entries(localData.aminoAcids).forEach(([key, data]) => {
    aminoAcids[key] = data.value;
  });

  return {
    ...localData,
    aminoAcids,
    kjeldahlNitrogen: localData.kjeldahlNitrogen || 0,
    kjeldahlNitrogenUnit: localData.kjeldahlNitrogenUnit === 'total nitrogen' ? 'totalNitrogenPercent' : 'crudeProteinPercent',
    kjeldahlNitrogenBasis: localData.kjeldahlNitrogenBasis === 'dry weight' ? 'dryWeight' : 'wetWeight',
    editHistory: localData.editHistory?.map(edit => ({
      date: edit.date,
      editedBy: edit.editedBy,
      changes: typeof edit.changes === 'string' ? JSON.parse(edit.changes) : edit.changes
    }))
  };
};

// Add type for expanded categories state
interface ExpandedCategories {
  [key: string]: boolean;
}

export default function Home() {
  // State variables
  const [formData, setFormData] = useState<FormData>({
    scientificName: '',
    foodCategory: '',
    aminoAcids: {},
    kjeldahlNitrogen: null,
    kjeldahlNitrogenUnit: 'total nitrogen',
    kjeldahlNitrogenBasis: 'dry weight',
    kjeldahlNitrogenFactor: null,
    moistureContent: null
  });

  const [snackbar, setSnackbar] = useState<SnackbarState>({
    open: false,
    message: '',
    severity: 'info'
  });

  const [saveKey, setSaveKey] = useState('');
  const [result, setResult] = useState<number | null>(null);
  const [citation, setCitation] = useState<Citation>({
    authors: '',
    year: '',
    title: '',
    journal: '',
    volume: '',
    issue: '',
    pages: '',
    doi: ''
  });

  const [inputs, setInputs] = useState<AminoAcidInput[]>(
    aminoAcids.map(name => ({
      name,
      value: '',
      calculatedValue: null
    }))
  );

  const [savedEntries, setSavedEntries] = useState<LocalKjeldahlData[]>([]);
  const [selectedEntry, setSelectedEntry] = useState<LocalKjeldahlData | null>(null);
  const [entryToDelete, setEntryToDelete] = useState<LocalKjeldahlData | null>(null);
  const [isLoadingDOI, setIsLoadingDOI] = useState(false);
  const [expandedCategories, setExpandedCategories] = useState<ExpandedCategories>({});
  const [selectedUnit, setSelectedUnit] = useState<string>('mg/g');
  const [showKeyDialog, setShowKeyDialog] = useState(false);
  const [dialogTitle, setDialogTitle] = useState('Enter Save Key');
  const [entryToEdit, setEntryToEdit] = useState<LocalKjeldahlData | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: SortableField; direction: 'asc' | 'desc' }>({
    key: 'scientificName',
    direction: 'asc'
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [totalAminoAcids, setTotalAminoAcids] = useState<number | null>(null);

  // Load saved data on mount
  useEffect(() => {
    loadSavedData();
  }, []);

  // Test connection on mount
  useEffect(() => {
    testConnection();
  }, []);

  // Fetch citation when DOI changes
  useEffect(() => {
    if (citation.doi) {
      fetchCitationFromDOI(citation.doi);
    }
  }, [citation.doi]);

  const loadSavedData = async () => {
    try {
      const data = await getSavedData();
      const convertedData = data.map(convertFromDatabaseKjeldahlData);
      setSavedEntries(convertedData);
    } catch (error) {
      console.error('Error loading saved data:', error);
      setSnackbar({ open: true, message: 'Error loading saved data', severity: 'error' });
    }
  };

  const resetForm = () => {
    setFormData({
      scientificName: '',
      foodCategory: '',
      aminoAcids: {},
      kjeldahlNitrogen: null,
      kjeldahlNitrogenUnit: 'total nitrogen',
      kjeldahlNitrogenBasis: 'dry weight',
      kjeldahlNitrogenFactor: null,
      moistureContent: null
    });
    setCitation({
      authors: '',
      year: '',
      title: '',
      journal: '',
      volume: '',
      issue: '',
      pages: '',
      doi: ''
    });
    setResult(null);
    setSaveKey('');
    setInputs(aminoAcids.map(name => ({
      name,
      value: '',
      calculatedValue: null
    })));
  };

  const calculateFactor = () => {
    // Get the converted total nitrogen % on dry weight basis
    const totalNitrogenDryWeight = convertKjeldahlNitrogen(
      formData.kjeldahlNitrogen,
      formData.kjeldahlNitrogenUnit,
      formData.kjeldahlNitrogenBasis,
      formData.kjeldahlNitrogenFactor,
      formData.moistureContent
    );
    
    if (totalNitrogenDryWeight === null) {
      setSnackbar({ open: true, message: 'Please enter a valid Kjeldahl nitrogen value', severity: 'error' });
      return;
    }

    // Calculate total amino acid content in mg/g
    let totalAminoAcidContent = 0;
    Object.values(formData.aminoAcids).forEach(data => {
      if (data && data.value > 0) {
        totalAminoAcidContent += data.value;
      }
    });

    if (totalAminoAcidContent === 0) {
      setSnackbar({ open: true, message: 'Please enter at least one amino acid value', severity: 'error' });
      return;
    }

    // Calculate the factor
    const factor = (totalAminoAcidContent/10) / totalNitrogenDryWeight;
    setResult(factor);
  };

  const handleInputChange = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = { ...newInputs[index], value };
    
    let calculatedValue: number | null = null;
    
    if (value.includes('+') || value.includes('-') || value.includes('*') || value.includes('/')) {
      try {
        const result = Function(`'use strict'; return (${value})`)();
        calculatedValue = convertToMgPerG(result, selectedUnit, newInputs[index].name);
      } catch {
        calculatedValue = null;
      }
    } else {
      const numValue = parseFloat(value);
      calculatedValue = convertToMgPerG(numValue, selectedUnit, newInputs[index].name);
    }
    
    newInputs[index].calculatedValue = calculatedValue;
    setInputs(newInputs);
    
    // Update formData.aminoAcids with the new value
    const aminoAcidName = newInputs[index].name;
    setFormData(prev => ({
      ...prev,
      aminoAcids: {
        ...prev.aminoAcids,
        [aminoAcidName]: {
          value: calculatedValue || 0,
          unit: selectedUnit
        }
      }
    }));
  };

  const handleSaveClick = () => {
    if (!citation.doi) {
      setSnackbar({ open: true, message: 'Please enter a DOI before saving', severity: 'error' });
      return;
    }
    setShowKeyDialog(true);
  };

  const handleDelete = (entry: LocalKjeldahlData) => {
    setEntryToDelete(entry);
    setSaveKey('');
    setDialogTitle('Enter Delete Key');
    setShowKeyDialog(true);
  };

  const handleEdit = (entry: LocalKjeldahlData) => {
    setEntryToEdit(entry);
    setSaveKey('');
    setDialogTitle('Enter Edit Key');
    setShowKeyDialog(true);
  };

  const handleDeleteConfirm = async () => {
    if (saveKey !== APP_CONFIG.deleteKey) {
      setSnackbar({
        open: true,
        message: 'Invalid delete key. Please enter the correct key to delete.',
        severity: 'error'
      });
      return;
    }

    if (!entryToDelete?.id) {
      console.error('No entry ID found for deletion');
      setSnackbar({
        open: true,
        message: 'Error: No entry ID found for deletion',
        severity: 'error'
      });
      return;
    }

    try {
      console.log('Attempting to delete entry with ID:', entryToDelete.id);
      await deleteFromDatabase(entryToDelete.id);
      console.log('Entry deleted successfully, reloading data...');
      await loadSavedData();
      setSnackbar({
        open: true,
        message: 'Entry deleted successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error deleting entry:', error);
      setSnackbar({
        open: true,
        message: 'Error deleting entry: ' + (error instanceof Error ? error.message : 'Unknown error'),
        severity: 'error'
      });
    }
    
    setShowKeyDialog(false);
    setEntryToDelete(null);
    setSaveKey('');
  };

  const renderEditHistory = (entry: LocalKjeldahlData) => {
    if (!entry.editHistory || entry.editHistory.length === 0) {
      return <Typography>No edit history available</Typography>;
    }

    return (
      <List>
        {entry.editHistory.map((edit, index) => (
          <ListItem key={index}>
            <ListItemText
              primary={`Edited by: ${edit.editedBy}`}
              secondary={`Date: ${new Date(edit.date).toLocaleString()} - ${edit.changes}`}
            />
          </ListItem>
        ))}
      </List>
    );
  };

  const handleEditConfirm = async () => {
    if (!entryToEdit || !saveKey) {
      setSnackbar({ open: true, message: 'Missing required information', severity: 'error' });
      return;
    }

    if (saveKey !== APP_CONFIG.editKey) {
      setSnackbar({ open: true, message: 'Invalid edit key', severity: 'error' });
      return;
    }

    try {
      calculateFactor();
      
      const updatedEntry: LocalKjeldahlData = {
        ...entryToEdit,
        scientificName: formData.scientificName,
        foodCategory: formData.foodCategory,
        aminoAcids: formData.aminoAcids,
        kjeldahlNitrogen: formData.kjeldahlNitrogen,
        kjeldahlNitrogenUnit: formData.kjeldahlNitrogenUnit,
        kjeldahlNitrogenBasis: formData.kjeldahlNitrogenBasis,
        kjeldahlNitrogenFactor: formData.kjeldahlNitrogenFactor,
        moistureContent: formData.moistureContent,
        factor: result || entryToEdit.factor,
        authors: citation.authors,
        year: citation.year,
        title: citation.title,
        journal: citation.journal,
        volume: citation.volume,
        issue: citation.issue,
        pages: citation.pages,
        doi: citation.doi,
        lastEditedBy: saveKey,
        lastEditedDate: new Date().toISOString(),
        editHistory: [
          ...(entryToEdit.editHistory || []),
          {
            date: new Date().toISOString(),
            editedBy: saveKey,
            changes: {
              message: 'Entry updated',
              previousValues: {
                scientificName: entryToEdit.scientificName,
                foodCategory: entryToEdit.foodCategory,
                kjeldahlNitrogen: entryToEdit.kjeldahlNitrogen,
                kjeldahlNitrogenUnit: entryToEdit.kjeldahlNitrogenUnit,
                kjeldahlNitrogenBasis: entryToEdit.kjeldahlNitrogenBasis,
                kjeldahlNitrogenFactor: entryToEdit.kjeldahlNitrogenFactor,
                moistureContent: entryToEdit.moistureContent,
                factor: entryToEdit.factor
              }
            }
          }
        ]
      };

      // Convert to database format
      const dbEntry = convertToDatabaseKjeldahlData(updatedEntry);
      
      // Update in database
      await updateInDatabase(updatedEntry.id, dbEntry);
      
      // Reload data
      await loadSavedData();
      
      // Show success message
      setSnackbar({ open: true, message: 'Entry updated successfully', severity: 'success' });
      
      // Reset form
      resetForm();
    } catch (error) {
      console.error('Error updating entry:', error);
      setSnackbar({ 
        open: true, 
        message: `Error updating entry: ${error instanceof Error ? error.message : 'Unknown error'}`, 
        severity: 'error' 
      });
    }
    
    setShowKeyDialog(false);
    setEntryToEdit(null);
    setSaveKey('');
  };

  const fetchCitationFromDOI = async (doi: string) => {
    setIsLoadingDOI(true);
    try {
      const response = await fetch(`https://api.crossref.org/works/${encodeURIComponent(doi)}`);
      const data = await response.json();
      const work = data.message;
      
      const authors = work.author?.map((author: any) => 
        `${author.family}${author.given ? `, ${author.given.charAt(0)}.` : ''}`
      ).join(', ') || '';

      const newCitation: Citation = {
        authors,
        year: work.published?.['date-parts']?.[0]?.[0]?.toString() || '',
        title: work.title?.[0] || '',
        journal: work['container-title']?.[0] || '',
        volume: work.volume || '',
        issue: work.issue || '',
        pages: work.page || '',
        doi: work.DOI || doi
      };

      setCitation(newCitation);
      setSnackbar({
        open: true,
        message: 'Citation details retrieved successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error fetching DOI:', error);
      setSnackbar({
        open: true,
        message: 'Error retrieving citation details. Please enter manually.',
        severity: 'error'
      });
    } finally {
      setIsLoadingDOI(false);
    }
  };

  const formatCitation = (citation: Citation): string => {
    if (!citation.authors || !citation.year || !citation.title) return '';
    
    let formattedCitation = `${citation.authors} (${citation.year}). ${citation.title}`;
    if (citation.journal) {
      formattedCitation += `. ${citation.journal}`;
      if (citation.volume) {
        formattedCitation += `, ${citation.volume}`;
        if (citation.issue) {
          formattedCitation += `(${citation.issue})`;
        }
      }
      if (citation.pages) {
        formattedCitation += `, ${citation.pages}`;
      }
    }
    formattedCitation += '.';
    if (citation.doi) {
      formattedCitation += ` https://doi.org/${citation.doi}`;
    }
    return formattedCitation;
  };

  const formatHowToCite = () => {
    return `Somasundaram, T. C., Anumolu, K., Samarakoon, D. M. B. K., & Anantharasah, L. (2025). DrThiruCSomasundaram/Kjeldahl: Kjeldahl Nitrogen Conversion Factor Calculator V1.2.0 (V1.2.0). Zenodo. https://doi.org/10.5281/zenodo.15144065`;
  };

  const handleDownloadCitation = () => {
    const risContent = `TY  - COMP
AU  - Somasundaram, Thiru C.; Anumolu, K.; Samarakoon, D. M. B. K.; Anantharasah, L.
PY  - 2025
TI  - Kjeldahl Nitrogen Conversion Factor Calculator V1.2.0
M3  - Software
PB  - Zenodo
DO  - 10.5281/zenodo.15144065 
UR  - https://doi.org/10.5281/zenodo.15144065
ER  -`;

    const blob = new Blob([risContent], { type: 'application/x-research-info-systems' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'citation.ris';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  const handleCategoryClick = (category: string) => {
    setExpandedCategories((prev: ExpandedCategories) => ({
      ...prev,
      [category]: !prev[category]
    }));
  };

  const getEntriesByCategory = () => {
    try {
      const grouped: Record<string, LocalKjeldahlData[]> = {};
      foodCategories.forEach(category => {
        grouped[category] = [];
      });
      savedEntries.forEach(entry => {
        if (entry.foodCategory in grouped) {
          grouped[entry.foodCategory].push(entry);
        } else {
          console.warn(`Unknown category found: ${entry.foodCategory}`);
          if (!grouped['Insects']) {
            grouped['Insects'] = [];
          }
          grouped['Insects'].push(entry);
        }
      });
      return grouped;
    } catch (error) {
      console.error('Error grouping entries:', error);
      return {};
    }
  };

  const getUniqueCitations = () => {
    const citationMap = new Map<string, { citation: Citation, refNumber: number }>();
    
    savedEntries.forEach((entry) => {
      if (!citationMap.has(entry.doi)) {
        citationMap.set(entry.doi, {
          citation: {
            authors: entry.authors,
            year: entry.year,
            title: entry.title,
            journal: entry.journal,
            volume: entry.volume,
            issue: entry.issue,
            pages: entry.pages,
            doi: entry.doi
          },
          refNumber: 0
        });
      }
    });

    const sortedCitations = Array.from(citationMap.entries())
      .sort((a, b) => {
        const getFirstAuthor = (authors: string) => {
          const firstAuthor = authors.split(',')[0].trim();
          return firstAuthor.toLowerCase();
        };
        
        return getFirstAuthor(a[1].citation.authors)
          .localeCompare(getFirstAuthor(b[1].citation.authors));
      });

    const sortedMap = new Map<string, { citation: Citation, refNumber: number }>();
    sortedCitations.forEach(([doi, data], index) => {
      sortedMap.set(doi, {
        ...data,
        refNumber: index + 1
      });
    });

    return sortedMap;
  };

  const getReferenceNumber = (doi: string) => {
    const citationMap = getUniqueCitations();
    return citationMap.get(doi)?.refNumber || 0;
  };

  const convertToMgPerG = (value: number, unit: string, aminoAcidName?: string): number => {
    if (isNaN(value) || value <= 0) return 0;
    
    switch (unit) {
      case 'mg/g':
        return value;
      case 'μmol/g':
        if (!aminoAcidName || !aminoAcidData[aminoAcidName]) {
          setSnackbar({ open: true, message: 'Amino acid name is required for μmol/g conversion', severity: 'error' });
          return 0;
        }
        // Convert μmol/g to mg/g using the specific molecular weight
        return (value * aminoAcidData[aminoAcidName].molarWeight) / 1000;
      case 'mg/100mg':
        return value * 10;
      case 'percent total amino acid':
        if (totalAminoAcids === null || isNaN(totalAminoAcids) || totalAminoAcids <= 0) {
          setSnackbar({ open: true, message: 'Please enter total amino acids value first', severity: 'error' });
          return 0;
        }
        return (value*10 /(100/totalAminoAcids));
      case 'μg/g':
        return value / 1000;
      case 'percent dryweight':
        return value * 10;
      case 'percent wet weight basis':
        if (formData.moistureContent === null || isNaN(formData.moistureContent) || formData.moistureContent <= 0) {
          setSnackbar({ open: true, message: 'Please enter moisture content for wet weight basis conversion', severity: 'error' });
          return 0;
        }
        // Convert from % wet weight to mg/g (dry weight)
        // First convert to mg/g wet weight
        const mgPerGWetWeight = value * 10;
        // Then convert to mg/g dry weight using moisture content
        return (mgPerGWetWeight * 100) / (100 - formData.moistureContent);
      default:
        return value;
    }
  };

  const sortData = (data: LocalKjeldahlData[]) => {
    return [...data].sort((a, b) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];
      if (aValue < bValue) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (aValue > bValue) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  };

  const handleSort = (key: SortableField) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const filterData = (data: LocalKjeldahlData[]) => {
    if (!searchQuery) return data;
    const query = searchQuery.toLowerCase();
    return data.filter(entry => 
      entry.scientificName.toLowerCase().includes(query) ||
      entry.foodCategory.toLowerCase().includes(query)
    );
  };

  const convertKjeldahlNitrogen = (value: number | null, unit: string, basis: string, factor: number | null, moisture: number | null): number => {
    if (value === null || isNaN(value) || value <= 0) return 0;
    
    let totalNitrogen = value;
    
    if (unit === 'crude protein' && factor !== null) {
      totalNitrogen = value / factor;
    }
    
    if (basis === 'wet weight' && moisture !== null && moisture > 0) {
      totalNitrogen = (totalNitrogen * 100) / (100 - moisture);
    }
    
    return totalNitrogen;
  };

  const handleKjeldahlChange = (value: string) => {
    if (value.includes('+') || value.includes('-') || value.includes('*') || value.includes('/')) {
      try {
        const result = Function(`'use strict'; return (${value})`)();
        setFormData({
          ...formData,
          kjeldahlNitrogen: isNaN(result) ? null : result
        });
      } catch {
        setFormData({
          ...formData,
          kjeldahlNitrogen: null
        });
      }
    } else {
      const numValue = parseFloat(value);
      setFormData({
        ...formData,
        kjeldahlNitrogen: isNaN(numValue) ? null : numValue
      });
    }
  };

  const handleTotalAminoAcidsChange = (value: string) => {
    const numValue = parseFloat(value);
    if (!isNaN(numValue) && numValue >= 0) {
      setTotalAminoAcids(numValue);
      if (selectedUnit === 'percent total amino acid') {
        const updatedAminoAcids = { ...formData.aminoAcids };
        Object.entries(updatedAminoAcids).forEach(([key, data]) => {
          if (data && data.value > 0) {
            const convertedValue = convertToMgPerG(
              data.value,
              data.unit,
              key
            );
            updatedAminoAcids[key] = {
              value: convertedValue,
              unit: data.unit
            };
          }
        });
        setFormData(prev => ({
          ...prev,
          aminoAcids: updatedAminoAcids
        }));
      }
    } else {
      setTotalAminoAcids(null);
    }
  };

  const handleScientificNameChange = (value: string) => {
    setFormData(prev => ({ ...prev, scientificName: value }));
  };

  const handleFoodCategoryChange = (value: string) => {
    setFormData(prev => ({ ...prev, foodCategory: value }));
  };

  // Move the testConnection function inside the component
  const testConnection = async () => {
    try {
      const isConnected = await testFirebaseConnection();
      if (isConnected) {
        setSnackbar({ open: false, message: 'Firebase connection successful!', severity: 'success' });
      } else {
        setSnackbar({ open: true, message: 'Firebase connection failed. Check console for details.', severity: 'error' });
      }
    } catch (error) {
      console.error('Error testing connection:', error);
      setSnackbar({ 
        open: true, 
        message: `Connection test failed: ${error instanceof Error ? error.message : 'Unknown error'}`, 
        severity: 'error' 
      });
    }
  };

  // Move the handleSave function inside the component
  const handleSave = async () => {
    if (!saveKey) {
      setSnackbar({ open: true, message: 'Please enter a save key', severity: 'error' });
      return;
    }

    if (!Object.keys(SAVE_KEYS).includes(saveKey)) {
      setSnackbar({ open: true, message: 'Invalid save key', severity: 'error' });
      return;
    }

    try {
      calculateFactor();
      
      // Create a clean entry object with all required fields
      const entry: LocalKjeldahlData = {
        id: Date.now().toString(),
        scientificName: formData.scientificName || '',
        foodCategory: formData.foodCategory || '',
        aminoAcids: Object.fromEntries(
          Object.entries(formData.aminoAcids).map(([key, value]) => [
            key,
            { value: value?.value || 0, unit: value?.unit || 'mg/g' }
          ])
        ),
        kjeldahlNitrogen: formData.kjeldahlNitrogen || 0,
        kjeldahlNitrogenUnit: formData.kjeldahlNitrogenUnit || 'total nitrogen',
        kjeldahlNitrogenBasis: formData.kjeldahlNitrogenBasis || 'dry weight',
        kjeldahlNitrogenFactor: formData.kjeldahlNitrogenFactor || null,
        moistureContent: formData.moistureContent || null,
        factor: result || 0,
        authors: citation.authors || '',
        year: citation.year || '',
        title: citation.title || '',
        journal: citation.journal || '',
        volume: citation.volume || '',
        issue: citation.issue || '',
        pages: citation.pages || '',
        doi: citation.doi || '',
        date: new Date().toISOString(),
        savedWithKey: saveKey,
        editHistory: [] // Initialize with empty array instead of undefined
      };

      // Convert to database format
      const dbEntry = convertToDatabaseKjeldahlData(entry);
      
      // Save to database
      await saveToDatabase(dbEntry);
      
      // Reload data
      await loadSavedData();
      
      // Show success message
      setSnackbar({ open: true, message: 'Entry saved successfully', severity: 'success' });
      
      // Reset form
      resetForm();
    } catch (error) {
      console.error('Error saving entry:', error);
      setSnackbar({ 
        open: true, 
        message: `Error saving entry: ${error instanceof Error ? error.message : 'Unknown error'}`, 
        severity: 'error' 
      });
    }
    
    setShowKeyDialog(false);
    setSaveKey('');
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <Box sx={{ display: 'flex', flex: 1 }}>
        <Container maxWidth="lg" sx={{ py: 2, marginRight: `${drawerWidth}px` }}>
          <Typography variant="h4" component="h1" gutterBottom align="center">
            Kjeldahl Nitrogen Conversion Factor Calculator
          </Typography>
          
          <Typography variant="subtitle1" align="center" gutterBottom>
            Created by Dr Thiru Chenduran Somasundaram, Deakin University
          </Typography>

          <Paper sx={{ p: 2, mb: 3 }}>
            <TextField
              fullWidth
              variant="outlined"
              placeholder="Search species or category..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
          </Paper>

          <Paper sx={{ p: 3, my: 2 }}>
            <Typography variant="h6" gutterBottom>
              Enter amino acid and nitrogen content for calculations
            </Typography>
            
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Scientific Name"
                  value={formData.scientificName}
                  onChange={(e) => handleScientificNameChange(e.target.value)}
                  required
                  helperText="Enter the scientific name of the species"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  select
                  label="Food Category"
                  value={formData.foodCategory}
                  onChange={(e) => handleFoodCategoryChange(e.target.value)}
                  required
                  helperText="Select the food category"
                >
                  {foodCategories.map((category) => (
                    <MenuItem key={category} value={category}>
                      {category}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Total Kjeldahl Nitrogen"
                  type="number"
                  value={formData.kjeldahlNitrogen || ''}
                  onChange={(e) => handleKjeldahlChange(e.target.value)}
                  InputProps={{
                    endAdornment: <InputAdornment position="end">%</InputAdornment>,
                  }}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Nitrogen Unit</InputLabel>
                  <Select
                    value={formData.kjeldahlNitrogenUnit}
                    onChange={(e) => setFormData({ 
                      ...formData, 
                      kjeldahlNitrogenUnit: e.target.value as 'total nitrogen' | 'crude protein' 
                    })}
                    label="Nitrogen Unit"
                  >
                    <MenuItem value="total nitrogen">Total Nitrogen %</MenuItem>
                    <MenuItem value="crude protein">Crude Protein %</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Basis</InputLabel>
                  <Select
                    value={formData.kjeldahlNitrogenBasis}
                    onChange={(e) => setFormData({ 
                      ...formData, 
                      kjeldahlNitrogenBasis: e.target.value as 'dry weight' | 'wet weight' 
                    })}
                    label="Basis"
                  >
                    <MenuItem value="dry weight">Dry Weight Basis</MenuItem>
                    <MenuItem value="wet weight">Wet Weight Basis</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              {formData.kjeldahlNitrogenUnit === 'crude protein' && (
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Kjeldahl Nitrogen Factor Used"
                    type="number"
                    value={formData.kjeldahlNitrogenFactor || ''}
                    onChange={(e) => {
                      const value = e.target.value === '' ? null : parseFloat(e.target.value);
                      setFormData({ ...formData, kjeldahlNitrogenFactor: value });
                    }}
                  />
                </Grid>
              )}
              {formData.kjeldahlNitrogenBasis === 'wet weight' && (
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Moisture Content"
                    type="number"
                    value={formData.moistureContent || ''}
                    onChange={(e) => {
                      const value = e.target.value === '' ? null : parseFloat(e.target.value);
                      setFormData({ ...formData, moistureContent: value });
                    }}
                    InputProps={{
                      endAdornment: <InputAdornment position="end">%</InputAdornment>,
                    }}
                  />
                </Grid>
              )}
              <Grid item xs={12}>
                <Typography variant="subtitle1" gutterBottom>
                  Total Nitrogen % (Dry Weight Basis): {convertKjeldahlNitrogen(
                    formData.kjeldahlNitrogen,
                    formData.kjeldahlNitrogenUnit,
                    formData.kjeldahlNitrogenBasis,
                    formData.kjeldahlNitrogenFactor,
                    formData.moistureContent
                  ).toFixed(2)}%
                </Typography>
              </Grid>

              <Grid item xs={12}>
                <Typography variant="subtitle1" gutterBottom>Amino acid content</Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>Amino Acid Unit</InputLabel>
                      <Select
                        value={selectedUnit}
                        onChange={(e) => setSelectedUnit(e.target.value)}
                        label="Amino Acid Unit"
                      >
                        {aminoAcidUnits.map((unit) => (
                          <MenuItem key={unit.value} value={unit.value}>
                            {unit.label}
                          </MenuItem>
                        ))}
                      </Select>
                      {selectedUnit === 'percent wet weight basis' && (
                        <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                          Note: Moisture content is required for conversion. Please enter it in the Kjeldahl nitrogen section.
                        </Typography>
                      )}
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      label="Total Amino Acids (%)"
                      type="number"
                      value={totalAminoAcids || ''}
                      onChange={(e) => handleTotalAminoAcidsChange(e.target.value)}
                      error={selectedUnit === 'percent total amino acid' && totalAminoAcids === null}
                      helperText={selectedUnit === 'percent total amino acid' && totalAminoAcids === null ? "Required when using % total amino acid unit" : ""}
                      disabled={selectedUnit !== 'percent total amino acid'}
                    />
                  </Grid>
                </Grid>
                <Grid container spacing={2} sx={{ mt: 1 }}>
                  {inputs.map((input, index) => (
                    <Grid item xs={12} sm={6} md={4} key={input.name}>
                      <TextField
                        fullWidth
                        label={input.name}
                        value={input.value}
                        onChange={(e) => handleInputChange(index, e.target.value)}
                        helperText={`Unit: ${selectedUnit}`}
                      />
                      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                        {input.calculatedValue !== null ? `Converted value: ${input.calculatedValue.toFixed(2)} mg/g` : 'No value entered'}
                      </Typography>
                    </Grid>
                  ))}
                </Grid>
              </Grid>

              {result !== null && (
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="DOI (Required for saving)"
                    value={citation.doi}
                    onChange={(e) => setCitation(prev => ({ ...prev, doi: e.target.value }))}
                    required
                    error={!citation.doi}
                    helperText={isLoadingDOI ? "Loading citation details..." : (!citation.doi ? "DOI is required to save data" : "Enter DOI to auto-fill citation details")}
                  />
                </Grid>
              )}

              <Grid item xs={12}>
                <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center' }}>
                  <Button variant="contained" onClick={calculateFactor}>
                    Calculate Factor
                  </Button>
                  {result !== null && (
                    <Button variant="contained" onClick={handleSaveClick}>
                      Save Data
                    </Button>
                  )}
                </Box>
              </Grid>
            </Grid>
          </Paper>

          {result !== null && (
            <Paper sx={{ p: 3, my: 3, boxShadow: 3 }}>
              <Typography variant="h6" gutterBottom sx={{ color: '#1a237e' }}>Results</Typography>
              <Typography variant="h5" gutterBottom sx={{ color: '#4a148c' }}>
                Kjeldahl Nitrogen Factor: {result.toFixed(2)}
              </Typography>
              <Typography sx={{ color: '#424242' }}>
                This factor can be used to convert Kjeldahl nitrogen measurements to protein content using:
                <Box component="span" sx={{ fontWeight: 'bold', display: 'block', mt: 1 }}>
                  Protein Content (%) = Kjeldahl Nitrogen (%) × {result.toFixed(2)}
                </Box>
              </Typography>
              <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
                <Button variant="contained" onClick={handleSaveClick}>
                  Save Data
                </Button>
              </Box>
            </Paper>
          )}

          {savedEntries.length > 0 && (
            <Paper sx={{ p: 3, my: 3, boxShadow: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                <Typography variant="h6" sx={{ color: '#1a237e' }}>Recent Kjeldahl nitrogen conversion factors</Typography>
                <Box sx={{ display: 'flex', gap: 2 }}>
                  <Button 
                    variant="outlined" 
                    onClick={handleDownloadCitation}
                    startIcon={<DownloadIcon />}
                    size="small"
                    sx={{ color: '#1a237e', borderColor: '#1a237e' }}
                  >
                    Cite this
                  </Button>
                  <Button
                    component={RouterLink}
                    to="/dashboard"
                    variant="contained"
                    color="primary"
                    sx={{ ml: 2 }}
                  >
                    View Dashboard
                  </Button>
                  <Button
                    component={RouterLink}
                    to="/entries"
                    variant="contained"
                    color="primary"
                    sx={{ ml: 2 }}
                  >
                    View All Entries
                  </Button>
                </Box>
              </Box>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell 
                        sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                        onClick={() => handleSort('scientificName')}
                      >
                        Scientific Name {sortConfig.key === 'scientificName' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                      </TableCell>
                      <TableCell 
                        sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                        onClick={() => handleSort('foodCategory')}
                      >
                        Category {sortConfig.key === 'foodCategory' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                      </TableCell>
                      <TableCell 
                        sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                        onClick={() => handleSort('factor')}
                      >
                        Conversion Factor {sortConfig.key === 'factor' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                      </TableCell>
                      <TableCell sx={{ fontWeight: 'bold', color: '#1a237e' }}>Reference</TableCell>
                      <TableCell sx={{ fontWeight: 'bold', color: '#1a237e' }}>Details</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {sortData(filterData(savedEntries))
                      .slice(0, 5)
                      .map((entry) => (
                        <TableRow key={entry.id} hover>
                          <TableCell>{entry.scientificName}</TableCell>
                          <TableCell>{entry.foodCategory}</TableCell>
                          <TableCell>{entry.factor.toFixed(2)}</TableCell>
                          <TableCell align="center">
                            <Typography sx={{ fontSize: '0.875rem' }}>
                              [{getReferenceNumber(entry.doi)}]
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Tooltip title="View Details">
                              <IconButton
                                size="small"
                                onClick={() => setSelectedEntry(entry)}
                                sx={{ color: '#1a237e' }}
                              >
                                <VisibilityIcon />
                              </IconButton>
                            </Tooltip>
                            {APP_CONFIG.allowEdit && (
                              <Tooltip title="Edit Entry">
                                <IconButton
                                  size="small"
                                  onClick={() => handleEdit(entry)}
                                  sx={{ color: '#1976d2' }}
                                >
                                  <EditIcon />
                                </IconButton>
                              </Tooltip>
                            )}
                            {APP_CONFIG.allowDelete && (
                              <Tooltip title="Delete Entry">
                                <IconButton
                                  size="small"
                                  onClick={() => handleDelete(entry)}
                                  sx={{ color: '#d32f2f' }}
                                >
                                  <DeleteIcon />
                                </IconButton>
                              </Tooltip>
                            )}
                          </TableCell>
                        </TableRow>
                      ))}
                  </TableBody>
                </Table>
              </TableContainer>

              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 2 }}>
                <Typography variant="body2" color="text.secondary">
                  Showing 5 of {savedEntries.length} entries
                </Typography>
                <Button
                  component={RouterLink}
                  to="/entries"
                  variant="text"
                  size="small"
                  sx={{ color: '#1a237e' }}
                >
                  View other species →
                </Button>
              </Box>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom sx={{ color: '#1a237e' }}>References</Typography>
                {Array.from(getUniqueCitations().values()).map(({ citation, refNumber }) => (
                  <Typography key={citation.doi} sx={{ mb: 1, pl: 3, textIndent: '-1.5em' }}>
                    [{refNumber}] {formatCitation(citation)}
                  </Typography>
                ))}
              </Box>
            </Paper>
          )}

          <Paper sx={{ p: 3, my: 3, boxShadow: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ color: '#1a237e' }}>How to Cite</Typography>
            <Typography paragraph sx={{ fontFamily: 'monospace', whiteSpace: 'pre-wrap' }}>
              {formatHowToCite()}
            </Typography>
            <Button 
              variant="outlined" 
              onClick={handleDownloadCitation}
              startIcon={<DownloadIcon />}
              sx={{ mt: 1 }}
            >
              Download Citation
            </Button>
          </Paper>
        </Container>

        <Drawer
          variant="permanent"
          anchor="right"
          sx={{
            width: drawerWidth,
            flexShrink: 0,
            '& .MuiDrawer-paper': {
              width: drawerWidth,
              boxSizing: 'border-box',
              padding: 1,
              bgcolor: '#fafafa',
              borderLeft: '1px solid rgba(0, 0, 0, 0.12)',
              mt: '48px'
            },
          }}
        >
          <Typography variant="h6" sx={{ mb: 1 }}>
          Kjeldahl nitrogen conversion factors of some edible Species
          </Typography>
          <List>
            {Object.entries(getEntriesByCategory()).map(([category, entries]) => (
              <Box key={category}>
                <ListItem 
                  button 
                  onClick={() => handleCategoryClick(category)}
                  sx={{ bgcolor: 'rgba(0, 0, 0, 0.04)', mb: 0.5, borderRadius: 1 }}
                >
                  <ListItemText 
                    primary={`${category} (${entries.length})`}
                    sx={{ color: '#1a237e' }}
                  />
                  {expandedCategories[category] ? <ExpandLess /> : <ExpandMore />}
                </ListItem>
                <Collapse in={expandedCategories[category]} timeout="auto" unmountOnExit>
                  <List component="div" disablePadding>
                    {entries.map((entry) => (
                      <ListItem
                        key={entry.id}
                        button
                        onClick={() => setSelectedEntry(entry)}
                        sx={{ pl: 4, mb: 0.5 }}
                      >
                        <ListItemText
                          primary={
                            <Box component="span" sx={{ display: 'flex', alignItems: 'start' }}>
                              {entry.scientificName}
                              <Typography component="sup" sx={{ ml: 0.5, fontSize: '0.7em' }}>
                                [{getReferenceNumber(entry.doi)}]
                              </Typography>
                            </Box>
                          }
                          secondary={`Factor: ${entry.factor.toFixed(2)}`}
                        />
                      </ListItem>
                    ))}
                  </List>
                </Collapse>
              </Box>
            ))}
          </List>
        </Drawer>
      </Box>

      <Box 
        component="footer" 
        sx={{ 
          py: 3, 
          px: 2, 
          mt: 'auto',
          backgroundColor: '#f5f5f5',
          borderTop: '1px solid #e0e0e0'
        }}
      >
        <Container maxWidth="lg">
          <Typography variant="body2" color="text.secondary" align="center">
            Created by Dr Thiru Chenduran Somasundaram, Deakin University
          </Typography>
          <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 1 }}>
            Somasundaram, T.C. et al., (2025). Kjeldahl Nitrogen Conversion Factor Calculator [Web application]. 
            Deakin University. https://DrThiruCSomasundaram.github.io/Kjeldahl/
          </Typography>
        </Container>
      </Box>

      <Dialog
        open={!!selectedEntry}
        onClose={() => setSelectedEntry(null)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          Details for {selectedEntry?.scientificName}
        </DialogTitle>
        <DialogContent>
          <Typography variant="subtitle1" gutterBottom>
            Citation: {selectedEntry && formatCitation({
              authors: selectedEntry.authors,
              year: selectedEntry.year,
              title: selectedEntry.title,
              journal: selectedEntry.journal,
              volume: selectedEntry.volume,
              issue: selectedEntry.issue,
              pages: selectedEntry.pages,
              doi: selectedEntry.doi
            })}
          </Typography>
          {selectedEntry?.lastEditedBy && selectedEntry.lastEditedDate && (
            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
              Last edited by: {selectedEntry.lastEditedBy} on {new Date(selectedEntry.lastEditedDate).toLocaleString()}
            </Typography>
          )}
          <Typography variant="subtitle1" gutterBottom>
            Amino Acid Composition (mg/g):
          </Typography>
          <Grid container spacing={2}>
            {selectedEntry && Object.entries(selectedEntry.aminoAcids).map(([acid, data]) => (
              <Grid item xs={6} key={acid}>
                <Typography>
                  {acid}: {data && typeof data.value === 'number' ? data.value.toFixed(2) : 'Not specified'}
                </Typography>
              </Grid>
            ))}
          </Grid>
          {selectedEntry?.editHistory && selectedEntry.editHistory.length > 0 && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle1" gutterBottom>
                Edit History:
              </Typography>
              {renderEditHistory(selectedEntry)}
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSelectedEntry(null)}>Close</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={showKeyDialog}
        onClose={() => {
          setShowKeyDialog(false);
          setEntryToDelete(null);
          setSaveKey('');
        }}
      >
        <DialogTitle>{dialogTitle}</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label={dialogTitle}
            type="password"
            fullWidth
            value={saveKey}
            onChange={(e) => setSaveKey(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => {
            setShowKeyDialog(false);
            setEntryToDelete(null);
            setSaveKey('');
          }}>Cancel</Button>
          <Button onClick={() => {
            if (entryToDelete) {
              handleDeleteConfirm();
            } else if (entryToEdit) {
              handleEditConfirm();
            } else {
              handleSave();
            }
          }}>Confirm</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
          severity={snackbar.severity}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
} 