import { useState, useEffect } from 'react';
import { Container, Typography, Box, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Button, IconButton, Tooltip, Dialog, DialogTitle, DialogContent, DialogActions, Grid, TextField, InputAdornment } from '@mui/material';
import { KjeldahlData, getSavedData } from '../data/database';
import VisibilityIcon from '@mui/icons-material/Visibility';
import DownloadIcon from '@mui/icons-material/Download';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import SearchIcon from '@mui/icons-material/Search';
import { useNavigate } from 'react-router-dom';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';

interface Citation {
  authors: string;
  year: string;
  title: string;
  journal: string;
  volume: string;
  issue: string;
  pages: string;
  doi: string;
}

type SortableField = keyof Pick<KjeldahlData, 'scientificName' | 'foodCategory' | 'factor'> | 'reference';

const citationGuide = {
  title: "How to Cite",
  content: [
    "Somasundaram, T. C., & Anumolu, K. (2025). Kjeldahl Nitrogen Conversion Factor Calculator V1.0.1 [Web Application]. Zenodo. https://doi.org/10.5281/zenodo.15095702"
    
  ]
};

export default function Entries() {
  const navigate = useNavigate();
  const [savedEntries, setSavedEntries] = useState<KjeldahlData[]>([]);
  const [selectedEntry, setSelectedEntry] = useState<KjeldahlData | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: SortableField; direction: 'asc' | 'desc' }>({
    key: 'scientificName',
    direction: 'asc'
  });
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    loadSavedData();
  }, []);

  const loadSavedData = async () => {
    try {
      const data = await getSavedData();
      setSavedEntries(data);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  const formatCitation = (citation: Citation): string => {
    if (!citation.authors || !citation.year || !citation.title) return '';
    
    let formattedCitation = `${citation.authors} (${citation.year}). ${citation.title}`;
    if (citation.journal) {
      formattedCitation += `. ${citation.journal}`;
      if (citation.volume) {
        formattedCitation += `, ${citation.volume}`;
        if (citation.issue) {
          formattedCitation += `(${citation.issue})`;
        }
      }
      if (citation.pages) {
        formattedCitation += `, ${citation.pages}`;
      }
    }
    formattedCitation += '.';
    if (citation.doi) {
      formattedCitation += ` https://doi.org/${citation.doi}`;
    }
    return formattedCitation;
  };

  const getUniqueCitations = () => {
    const citationMap = new Map<string, { citation: Citation, refNumber: number }>();
    
    // First, collect all unique citations
    savedEntries.forEach((entry) => {
      if (!citationMap.has(entry.doi)) {
        citationMap.set(entry.doi, {
          citation: {
            authors: entry.authors,
            year: entry.year,
            title: entry.title,
            journal: entry.journal,
            volume: entry.volume,
            issue: entry.issue,
            pages: entry.pages,
            doi: entry.doi
          },
          refNumber: 0 // Temporary refNumber, will be updated after sorting
        });
      }
    });

    // Convert map to array for sorting
    const sortedCitations = Array.from(citationMap.entries())
      .sort((a, b) => {
        // Get first author's name from each citation
        const getFirstAuthor = (authors: string) => {
          const firstAuthor = authors.split(',')[0].trim();
          return firstAuthor.toLowerCase();
        };
        
        return getFirstAuthor(a[1].citation.authors)
          .localeCompare(getFirstAuthor(b[1].citation.authors));
      });

    // Create new map with sorted reference numbers
    const sortedMap = new Map<string, { citation: Citation, refNumber: number }>();
    sortedCitations.forEach(([doi, data], index) => {
      sortedMap.set(doi, {
        ...data,
        refNumber: index + 1
      });
    });

    return sortedMap;
  };

  const getReferenceNumber = (doi: string) => {
    const citationMap = getUniqueCitations();
    return citationMap.get(doi)?.refNumber || 0;
  };

  const filterData = (data: KjeldahlData[]) => {
    if (!searchQuery) return data;
    const query = searchQuery.toLowerCase();
    return data.filter(entry => 
      entry.scientificName.toLowerCase().includes(query) ||
      entry.foodCategory.toLowerCase().includes(query) ||
      entry.authors.toLowerCase().includes(query) ||
      entry.year.includes(query)
    );
  };

  const sortData = (data: KjeldahlData[]) => {
    return [...data].sort((a, b) => {
      if (sortConfig.key === 'reference') {
        const aRef = getReferenceNumber(a.doi);
        const bRef = getReferenceNumber(b.doi);
        return sortConfig.direction === 'asc' ? aRef - bRef : bRef - aRef;
      }
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];
      if (aValue < bValue) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (aValue > bValue) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  };

  const handleSort = (key: SortableField) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const handleDownloadCitation = () => {
    const risContent = `TY  - COMP
AU  - Somasundaram, Thiru C.; Anumolu, K.
PY  - 2025
TI  - Kjeldahl Nitrogen Conversion Factor Calculator V1.0.1
M3  - Software
PB  - Zenodo
DO  - 10.5281/zenodo.15095702 
UR  - https://doi.org/10.5281/zenodo.15095702
ER  -`;

    const blob = new Blob([risContent], { type: 'application/x-research-info-systems' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'citation.ris';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
        <IconButton onClick={() => navigate('/')} sx={{ mr: 2 }}>
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h4" component="h1">
          Complete Database of Kjeldahl Nitrogen Conversion Factors
        </Typography>
      </Box>

      <Box sx={{ display: 'flex', gap: 3 }}>
        <Paper sx={{ p: 3, width: 300, flexShrink: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <HelpOutlineIcon sx={{ mr: 1, color: '#1a237e' }} />
            <Typography variant="h6" sx={{ color: '#1a237e' }}>
              {citationGuide.title}
            </Typography>
          </Box>
          {citationGuide.content.map((line, index) => (
            <Typography 
              key={index} 
              variant="body2" 
              sx={{ 
                mb: 1,
                color: line.startsWith('Note:') ? '#d32f2f' : 'inherit'
              }}
            >
              {line}
            </Typography>
          ))}
        </Paper>

        <Box sx={{ flexGrow: 1 }}>
          <Paper sx={{ p: 2, mb: 3 }}>
            <TextField
              fullWidth
              variant="outlined"
              placeholder="Search by species, category, author, or year..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
          </Paper>

          <Paper sx={{ p: 3, mb: 3 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="h6" sx={{ color: '#1a237e' }}>
                
              </Typography>
              <Button 
                variant="outlined" 
                onClick={handleDownloadCitation}
                startIcon={<DownloadIcon />}
                size="small"
                sx={{ color: '#1a237e', borderColor: '#1a237e' }}
              >
                Cite this
              </Button>
            </Box>

            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell 
                      sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                      onClick={() => handleSort('scientificName')}
                    >
                      Scientific Name {sortConfig.key === 'scientificName' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                    </TableCell>
                    <TableCell 
                      sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                      onClick={() => handleSort('foodCategory')}
                    >
                      Category {sortConfig.key === 'foodCategory' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                    </TableCell>
                    <TableCell 
                      sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                      onClick={() => handleSort('factor')}
                    >
                      Conversion Factor {sortConfig.key === 'factor' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                    </TableCell>
                    <TableCell 
                      sx={{ fontWeight: 'bold', color: '#1a237e', cursor: 'pointer' }}
                      onClick={() => handleSort('reference')}
                    >
                      Reference {sortConfig.key === 'reference' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                    </TableCell>
                    <TableCell sx={{ fontWeight: 'bold', color: '#1a237e' }}>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {sortData(filterData(savedEntries)).map((entry) => (
                    <TableRow key={entry.id} hover>
                      <TableCell>{entry.scientificName}</TableCell>
                      <TableCell>{entry.foodCategory}</TableCell>
                      <TableCell>{entry.factor.toFixed(2)}</TableCell>
                      <TableCell align="center">
                        <Typography sx={{ fontSize: '0.875rem' }}>
                          [{getReferenceNumber(entry.doi)}]
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Tooltip title="View Details">
                          <IconButton
                            size="small"
                            onClick={() => setSelectedEntry(entry)}
                            sx={{ color: '#1a237e' }}
                          >
                            <VisibilityIcon />
                          </IconButton>
                        </Tooltip>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Box sx={{ mt: 3 }}>
              <Typography variant="h6" gutterBottom sx={{ color: '#1a237e' }}>References</Typography>
              {Array.from(getUniqueCitations().values()).map(({ citation, refNumber }) => (
                <Typography key={citation.doi} sx={{ mb: 1, pl: 3, textIndent: '-1.5em' }}>
                  [{refNumber}] {formatCitation(citation)}
                </Typography>
              ))}
            </Box>
          </Paper>
        </Box>
      </Box>

      <Dialog
        open={!!selectedEntry}
        onClose={() => setSelectedEntry(null)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          Details for {selectedEntry?.scientificName}
        </DialogTitle>
        <DialogContent>
          <Typography variant="subtitle1" gutterBottom>
            Citation: {selectedEntry && formatCitation({
              authors: selectedEntry.authors,
              year: selectedEntry.year,
              title: selectedEntry.title,
              journal: selectedEntry.journal,
              volume: selectedEntry.volume,
              issue: selectedEntry.issue,
              pages: selectedEntry.pages,
              doi: selectedEntry.doi
            })}
          </Typography>
          {/* <Typography variant="subtitle1" gutterBottom>
            Kjeldahl Nitrogen: {selectedEntry?.kjeldahlNitrogen.toFixed(2)}% 
            ({selectedEntry?.kjeldahlNitrogenUnit === 'crudeProteinPercent' ? 'Crude Protein' : 'Total Nitrogen'}) 
            on {selectedEntry?.kjeldahlNitrogenBasis === 'wetWeight' ? 'Wet Weight' : 'Dry Weight'} basis
          </Typography>
          {selectedEntry?.kjeldahlNitrogenUnit === 'crudeProteinPercent' && (
            <Typography variant="subtitle1" gutterBottom>
              Kjeldahl Nitrogen Factor Used: {selectedEntry?.kjeldahlNitrogenFactor?.toFixed(2) || 'N/A'}
            </Typography>
          )}
          {selectedEntry?.kjeldahlNitrogenBasis === 'wetWeight' && (
            <Typography variant="subtitle1" gutterBottom>
              Moisture Content: {selectedEntry?.moistureContent?.toFixed(2) || 'N/A'}%
            </Typography>
          )} */}
          <Typography variant="subtitle1" gutterBottom>
            Amino Acid Composition (mg/g):
          </Typography>
          <Grid container spacing={2}>
            {selectedEntry && Object.entries(selectedEntry.aminoAcids).map(([acid, value]) => (
              <Grid item xs={6} key={acid}>
                <Typography>
                  {acid}: {value !== null ? value.toFixed(2) : 'Not specified'}
                </Typography>
              </Grid>
            ))}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSelectedEntry(null)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
} 