import { 
  collection, 
  addDoc, 
  getDocs, 
  deleteDoc, 
  doc, 
  query, 
  orderBy, 
  updateDoc,
  getDoc,
  serverTimestamp,
  FirestoreError
} from 'firebase/firestore';
import { db } from '../config/firebase';

// Collection name for Kjeldahl data
const COLLECTION_NAME = 'kjeldahlData';

// Interface for Kjeldahl data
export interface KjeldahlData {
  id: string;
  scientificName: string;
  foodCategory: string;
  aminoAcids: Record<string, number | null>;
  kjeldahlNitrogen: number;
  kjeldahlNitrogenUnit: 'totalNitrogenPercent' | 'crudeProteinPercent';
  kjeldahlNitrogenBasis: 'dryWeight' | 'wetWeight';
  kjeldahlNitrogenFactor: number | null;
  moistureContent: number | null;
  factor: number;
  authors: string;
  year: string;
  title: string;
  journal: string;
  volume: string;
  issue: string;
  pages: string;
  doi: string;
  date: string;
  savedWithKey: string;
  lastEditedBy?: string;
  lastEditedDate?: string;
  editHistory?: Array<{
    date: string;
    editedBy: string;
    changes: Record<string, unknown>;
  }>;
  timestamp?: any; // Firestore timestamp
}

/**
 * Format error message from Firestore error
 */
const formatFirestoreError = (error: unknown): string => {
  if (error instanceof FirestoreError) {
    return `Firebase error (${error.code}): ${error.message}`;
  }
  return error instanceof Error ? error.message : 'Unknown error';
};

/**
 * Save data to Firestore
 * @param data The data to save
 * @returns Promise with the document ID if successful
 */
export const saveToDatabase = async (data: KjeldahlData): Promise<string> => {
  try {
    console.log('Attempting to save data to Firestore:', data);
    
    // Add timestamp
    const dataWithTimestamp = {
      ...data,
      timestamp: serverTimestamp()
    };
    
    // Add to collection
    const docRef = await addDoc(collection(db, COLLECTION_NAME), dataWithTimestamp);
    console.log('Document written with ID: ', docRef.id);
    
    // Update the document with its ID
    await updateDoc(doc(db, COLLECTION_NAME, docRef.id), {
      id: docRef.id
    });
    
    return docRef.id;
  } catch (error) {
    console.error('Error saving to database:', error);
    throw new Error(`Failed to save to database: ${formatFirestoreError(error)}`);
  }
};

/**
 * Get all saved data from Firestore
 * @returns Promise with array of saved data
 */
export const getSavedData = async (): Promise<KjeldahlData[]> => {
  try {
    console.log('Fetching data from Firestore');
    
    // Create query with ordering
    const q = query(collection(db, COLLECTION_NAME), orderBy('date', 'desc'));
    
    // Execute query
    const querySnapshot = await getDocs(q);
    
    // Map results
    const results = querySnapshot.docs.map(doc => {
      const data = doc.data();
      return {
        ...data,
        id: doc.id  // Ensure the document ID is set from Firestore
      } as KjeldahlData;
    });
    
    console.log(`Retrieved ${results.length} documents from Firestore`);
    return results;
  } catch (error) {
    console.error('Error getting data from database:', error);
    throw new Error(`Failed to retrieve data: ${formatFirestoreError(error)}`);
  }
};

/**
 * Delete a document from Firestore
 * @param id The document ID to delete
 * @returns Promise with boolean indicating success
 */
export const deleteFromDatabase = async (id: string): Promise<boolean> => {
  try {
    console.log(`Attempting to delete document with ID: ${id}`);
    
    if (!id) {
      throw new Error('Document ID is required for deletion');
    }
    
    // Get document reference
    const docRef = doc(db, COLLECTION_NAME, id);
    
    // Delete document
    await deleteDoc(docRef);
    
    console.log('Document successfully deleted');
    return true;
  } catch (error) {
    console.error('Error deleting from database:', error);
    throw new Error(`Failed to delete document: ${formatFirestoreError(error)}`);
  }
};

/**
 * Update a document in Firestore
 * @param id The document ID to update
 * @param data The new data
 * @returns Promise with boolean indicating success
 */
export const updateInDatabase = async (id: string, data: Partial<KjeldahlData>): Promise<boolean> => {
  try {
    console.log(`Attempting to update document with ID: ${id}`);
    
    // Get document reference
    const docRef = doc(db, COLLECTION_NAME, id);
    
    // Check if document exists
    const docSnap = await getDoc(docRef);
    if (!docSnap.exists()) {
      throw new Error(`Document with ID ${id} does not exist`);
    }
    
    // Add timestamp and lastEditedDate
    const dataWithTimestamp = {
      ...data,
      lastEditedDate: new Date().toISOString(),
      timestamp: serverTimestamp()
    };
    
    // Update document
    await updateDoc(docRef, dataWithTimestamp);
    
    console.log('Document successfully updated');
    return true;
  } catch (error) {
    console.error('Error updating document in database:', error);
    throw new Error(`Failed to update document: ${formatFirestoreError(error)}`);
  }
};

/**
 * Test Firebase connection
 * @returns Promise with boolean indicating success
 */
export const testFirebaseConnection = async (): Promise<boolean> => {
  try {
    console.log('Testing Firebase connection');
    
    // Create a test document
    const testDoc = {
      test: 'This is a test document',
      timestamp: serverTimestamp()
    };
    
    // Add to collection
    const docRef = await addDoc(collection(db, 'test-collection'), testDoc);
    console.log('Test document written with ID: ', docRef.id);
    
    // Delete the test document
    await deleteDoc(doc(db, 'test-collection', docRef.id));
    console.log('Test document deleted');
    
    return true;
  } catch (error) {
    console.error('Error testing Firebase connection:', formatFirestoreError(error));
    return false;
  }
}; 